// ─── File: LoanFacadeDemo.java ───
// Facade pattern: ONE simple method coordinates FIVE subsystem classes.
// Each class below would be its own file in a real project.
package com.bank.loan;

import java.math.BigDecimal;
import java.util.logging.*;

public class LoanFacadeDemo {

    private static final Logger log = Logger.getLogger("Loan");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Build the complex subsystem once.
        LoanApprovalFacade facade = new LoanApprovalFacade(
                new CreditScoreService(), new IncomeVerifier(),
                new PropertyValuer(), new LegalTitleChecker(),
                new DisbursementService());

        // Client uses ONE simple call — it never touches the 5 subsystems directly.
        String decision = facade.approveHomeLoan(
                "SAV2001", "Rajesh Kumar",
                new BigDecimal("4000000"),   // loan amount requested
                new BigDecimal("1200000"),   // annual income
                new BigDecimal("6000000"));  // property value
        log.info(() -> "FINAL DECISION for Rajesh: " + decision);
    }
}

// ─── facade/LoanApprovalFacade.java ───
// Thin coordinator: delegates in the correct order, adds NO business rules itself.
class LoanApprovalFacade {
    private static final Logger log = Logger.getLogger("Loan");
    private final CreditScoreService credit;
    private final IncomeVerifier income;
    private final PropertyValuer property;
    private final LegalTitleChecker legal;
    private final DisbursementService disbursement;

    LoanApprovalFacade(CreditScoreService credit, IncomeVerifier income,
                       PropertyValuer property, LegalTitleChecker legal,
                       DisbursementService disbursement) {
        this.credit = credit; this.income = income; this.property = property;
        this.legal = legal; this.disbursement = disbursement;
    }

    // The ONE coarse-grained method clients call. Orchestration only.
    String approveHomeLoan(String accountId, String name, BigDecimal loanAmount,
                           BigDecimal annualIncome, BigDecimal propertyValue) {
        log.info(() -> "FACADE approveHomeLoan for " + name + " amount Rs." + loanAmount);

        if (!credit.isCreditGood(accountId))                 return "REJECTED: low credit score";
        if (!income.canAfford(annualIncome, loanAmount))     return "REJECTED: income too low";
        if (!property.loanWithinValue(loanAmount, propertyValue)) return "REJECTED: LTV too high";
        if (!legal.titleClear(accountId))                    return "REJECTED: legal title issue";

        String ref = disbursement.disburse(accountId, loanAmount);
        return "APPROVED and DISBURSED, ref " + ref;
    }
}

// ─── subsystem/CreditScoreService.java ───
class CreditScoreService {
    private static final Logger log = Logger.getLogger("Loan");
    boolean isCreditGood(String accountId) {
        int score = 760;                                     // real impl calls a bureau
        log.fine(() -> "credit score for " + accountId + " = " + score);
        return score >= 700;
    }
}

// ─── subsystem/IncomeVerifier.java ───
class IncomeVerifier {
    private static final Logger log = Logger.getLogger("Loan");
    boolean canAfford(BigDecimal annualIncome, BigDecimal loanAmount) {
        boolean ok = loanAmount.compareTo(annualIncome.multiply(new BigDecimal("5"))) <= 0;
        log.fine(() -> "income check ok=" + ok);
        return ok;
    }
}

// ─── subsystem/PropertyValuer.java ───
class PropertyValuer {
    private static final Logger log = Logger.getLogger("Loan");
    boolean loanWithinValue(BigDecimal loanAmount, BigDecimal propertyValue) {
        BigDecimal maxLoan = propertyValue.multiply(new BigDecimal("0.80"));  // 80% LTV
        boolean ok = loanAmount.compareTo(maxLoan) <= 0;
        log.fine(() -> "LTV check ok=" + ok + " maxLoan=" + maxLoan);
        return ok;
    }
}

// ─── subsystem/LegalTitleChecker.java ───
class LegalTitleChecker {
    private static final Logger log = Logger.getLogger("Loan");
    boolean titleClear(String accountId) {
        log.fine(() -> "legal title clear for " + accountId);
        return true;
    }
}

// ─── subsystem/DisbursementService.java ───
class DisbursementService {
    private static final Logger log = Logger.getLogger("Loan");
    String disburse(String accountId, BigDecimal amount) {
        String ref = "LN-" + System.currentTimeMillis();
        log.info(() -> "disbursed Rs." + amount + " to " + accountId + " ref " + ref);
        return ref;
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
